# Simple Python demonstration script
# ~684 KB in file size
# Test Case for large file handling

"""
A demonstration module containing basic Python operations and a large lookup table.
"""

def greet(name: str) -> str:
    return f"Hello, {name}!"

def fibonacci(n: int) -> list[int]:
    if n <= 0:
        return []
    fib = [0, 1]
    while len(fib) < n:
        fib.append(fib[-1] + fib[-2])
    return fib[:n]

def calculate_stats(numbers: list[float]) -> dict:
    if not numbers:
        return {"min": 0, "max": 0, "sum": 0, "avg": 0}
    return {
        "min": min(numbers),
        "max": max(numbers),
        "sum": sum(numbers),
        "avg": sum(numbers) / len(numbers),
    }

